import{_ as e,H as t,f as a,i as E}from"./chunks/framework.BH2BK_3i.js";const c=JSON.parse('{"title":"第五封信-基本上一个有用的都没有","description":"","frontmatter":{},"headers":[],"relativePath":"去无方向的信/第五封信-基本上一个有用的都没有.md","filePath":"去无方向的信/第五封信-基本上一个有用的都没有.md","lastUpdated":1795542896000}'),_={name:"去无方向的信/第五封信-基本上一个有用的都没有.md"};function s(n,p,A,i,r,o){return t(),a("div",null,[...p[0]||(p[0]=[E('<h1 id="第五封信-基本上一个有用的都没有" tabindex="-1">第五封信-基本上一个有用的都没有 <a class="header-anchor" href="#第五封信-基本上一个有用的都没有" aria-label="Permalink to &quot;第五封信-基本上一个有用的都没有&quot;">​</a></h1><p>生生：</p><p>你好哇。</p><p>上次我说“现在的数码相机用起来好艰难啊”，你好像不是很认同，给我举了很多例子，用于说明现在相机里的高科技做到了多少以前的机械相机做不到的事情，所以，我觉得有必要先把这事儿说明白，然后再说然后。</p><p>现在的相机，功能越来越强大，操作越来越自动化，但其实，在我看来，这些高科技，对于大多数人来说，非但不是解放，反而是束缚。</p><p>相机做了很多本应该我们自己做的事儿，我也希望有朝一日他能把这些事儿做得特好，但目前看，他好像还不太行呢。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E4%25BA%2594%25E5%25B0%2581%25E4%25BF%25A1-%25E5%259F%25BA%25E6%259C%25AC%25E4%25B8%258A%25E4%25B8%2580%25E4%25B8%25AA%25E6%259C%2589%25E7%2594%25A8%25E7%259A%2584%25E9%2583%25BD%25E6%25B2%25A1%25E6%259C%2589/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E4%25BA%2594%25E5%25B0%2581%25E4%25BF%25A1-%25E5%259F%25BA%25E6%259C%25AC%25E4%25B8%258A%25E4%25B8%2580%25E4%25B8%25AA%25E6%259C%2589%25E7%2594%25A8%25E7%259A%2584%25E9%2583%25BD%25E6%25B2%25A1%25E6%259C%2589/1.png" alt=""></a></p><p>比如那些自动曝光模式：</p><p>A 档（有些相机叫 Av 档），光圈优先档，这个模式代表着你可以自己调节你需要的光圈值，但你把快门和 ISO 的选择权交给了相机。</p><p>如果是白天拍，也许还好，只是也许还好，但如果光线稍差一点点，就很容易出问题。</p><p>S 档（有些相机叫 Tv 档），快门优先档，这个模式代表着你可以自己调节你需要的快门值，但你把光圈和 ISO 的选择权交给了相机。</p><p>半 M 档（ISO 自动），这个模式代表着你可以自己调节你需要的光圈值和快门值，但你把 ISO的选择权交给了相机。</p><p>P 档，完全自动档，这个模式代表着你不如直接用手机拍。</p><p>我们甚至都可以不用分光线是好是坏了，在我看来，以上这些自动曝光模式全都容易出问题，因为如果你的曝光模式是自动的，那很大概率你的测光模式也是自动的。</p><p>所以，接着说那些自动测光模式。</p><p>什么是自动测光？自动测光就是相机自己觉得怎么曝光合适他就怎么曝，他会给你匹配一套曝光参数，但问题就在于：首先，通常他并不知道我到底需要什么曝光；其次，即便他蒙对了曝光，他也不知道我具体需要什么样的光圈值，什么样的快门值，什么样的 ISO 值……因为我之前讲过，我能用好多种不同的曝光参数组合拍出曝光一致的照片儿，但不是每种组合都适用于当时当下的场景。</p><p>所以，相机的自动测光只能测出一个他觉得准确的曝光，这涉及“18% 灰”这个概念，后面我们可能会讲到，也可能不会。</p><p>说回来，先不考虑“准确曝光”是否是个伪命题，反正“他觉得准确的”基本都不怎么靠谱儿，因为，他不知道什么叫靠谱儿。</p><p>常见的自动测光模式有平均测光、中央重点测光和点测光，在这三种自动测光模式的基础上，现在还衍生出来好多“更精确”的自动测光模式。</p><p>聊到这儿，你可能会想到还有一个叫“曝光补偿”的东西，好像在相机测不准光的时候有用处，让我来尽可能形象地描述一下这个东西。</p><p>相机看到一个场景，他给你配了一档光圈，配了一档快门，配了一档 ISO，组合起来固定住了一个曝光值，而曝光补偿就像是你在跟相机商量，如果你觉得他把照片儿搞得太亮了，或者说你怕他把照片儿搞得太亮了，你就减一点曝光补偿，他一听你说要暗一点，他就随便缩缩光圈，或者随便催催快门，或者随便降降 ISO，于是，照片儿就比刚才暗了一点，就达到了你想要的效果。</p><p>反之亦然。</p><p>但你想，如果我跟他商量，意味着我基本相信他的能力，稍有偏差，咱们可以商量着来，但问题是，我完全不相信他的能力，我觉得他除了麻烦事儿特别多之外什么都不会……所以，不用拿着曝光补偿跟相机商量，就直接给他下死命令，全手动，让他干嘛他干嘛就好了。</p><p>接下来就该到自动对焦模式了：</p><p>说实话，我是真懒得列举各种各样的自动对焦模式了，总之就一句话，都不好用，因为相机不会知道你的意图，而且，再快的自动对焦也没有不对焦快，有关这一点，我后面会很重点地讲。</p><p>最后就是自动白平衡什么的那些了……算了吧，不说了。</p><p>现在的相机给我们的选择太多了，但我们都是有选择困难症的人，选择多了基本等于什么也决定不了。</p><p>这有点像下馆子，大多数情况下，如果一家馆子只做一两样东西，通常都会做得比较精细，比较好吃，同时，我们进这家馆子吃饭也会感觉很轻松。毕竟我喜欢的是吃饭，不是看菜单做选择题，不是捧着厚厚的菜本，被迫在五分钟之内，要从五种鸡、六种鸭、七种鱼、十几种牛羊肉和好几万种主食蔬菜甜品里选出两三道菜。</p><p>我感觉有这么个悖论：如果你有的是时间，你当然可以跟数码相机的自动功能们叫劲，你可以让他们自动得服服帖帖的，但如果你能把相机调教得这么好，意味着你已经非常行家了。而如果你都已经是行家了，你又肯定不会依赖自动功能，即便偶尔用自动功能，你也必然能非常准确地判断出在什么情况下可以借助相机的哪一项自动功能来拍，在什么情况下又完全不能相信相机的决定。</p><p>说回来，如果你有的是时间，你早已经能把所有该设置的都设置好了，何必跟相机叫劲呢，多浪费生命啊。</p><p>总而言之，这么说吧，在绝大多数日常拍摄的情况下，我们只有把相机里所有默认开启的“自动功能”都给关上，才有可能真的拍到一些什么，因为在我看来，那些自动功能基本真的是一个有用的都没有。</p><p>反而是专业拍摄，偶尔可以用到那些自动功能，很奇怪哈！</p><p>咱们之后有时间再继续聊。</p>',33)])])}const l=e(_,[["render",s]]);export{c as __pageData,l as default};
